ROOT=Path(__file__).resolve().parents[2];DATA=prior.DATA;META=prior.META
read=prior.read;pin=prior.pin;identity=prior.identity;encoded=prior.encoded;require=prior.require
FOLDER='docs/literature/matrixeqtl-catalog-admission';ROLES='docs/literature/matrixeqtl-source-audit/ROLES.json';Q='docs/literature/matrixeqtl-validation/QUALIFICATION.json'
COVERAGE=DATA+'/matrixeqtl-source-role-coverage.json';PROOF=DATA+'/matrixeqtl-catalog-validation.json';SOURCE='src/main/java/org/jlinalg/cli/MatrixEqtlNativeCli.java'
