def predecessor(root,before):
 folder=root/prior.FOLDER;base=read(folder/'BASELINE.json');require(pin(folder/'metadata-before.zip')==base['archive'],'Earlier GraphTyper archive changed')
 with zipfile.ZipFile(folder/'metadata-before.zip')as archive:
  require(set(archive.namelist())==set(META),'Earlier archive population changed');older={n:archive.read(n)for n in META}
 require({n:identity(raw)for n,raw in older.items()}==base['metadata'],'Earlier archived bytes changed');registry=prior.predecessor(root,older);expected,registry,_=prior.transition(older,registry,read(root/prior.ROLES)['roles']);require(expected==before and read(folder/'REGISTRY.json')==registry,'Predecessor differs from exact retained GraphTyper transition');return registry

def transition(before,registry,roles):
 papers,inventory,summary,ledger=[json.loads(before[META[i]])for i in [0,1,2,7]];require((len(papers),len(inventory),sum(len(p['tools'])for p in papers),len(ledger['reviews']),len(registry))==(250,453,2734,1840,492),'Predecessor totals changed');require({r['paper_id']for r in roles}=={'P169','P185','P213','P219'}and len(roles)==4,'All four matrixeqtl source roles required');coverage=[]
 for role in roles:
  paper=next(p for p in papers if p['paper_id']==role['paper_id']);uses=[u for u in paper['tools']if u['tool_id']=='matrixeqtl'];require(len(uses)==1 and uses[0]==role['raw_observation_preserved'],'Original observation changed');use=uses[0];require(not any(x['pmcid']==paper['pmcid']and x['tool_id']=='matrixeqtl'for x in ledger['reviews']),'matrixeqtl role already reviewed')
  qualified={k:copy.deepcopy(role[k])for k in ['paper_id','source_role','reported_version','runtime_scope','remaining_scope','exact_author_recipe_qualified','whole_paper_reproduced']};coverage.append(qualified)
  use.update(review_status=REVIEWED,use_summary=role['use_summary'],implementation_scope_note=SCOPE+' '+role['remaining_scope']+' '+ACTION,evidence_selection='individually-reviewed-all-primary-matrixeqtl-contexts',supporting_evidence=copy.deepcopy(role['primary_anchors']),source_role_qualification=qualified)
  ledger['reviews'].append(dict(pmcid=paper['pmcid'],doi=paper['doi'],tool_id='matrixeqtl',evidence_paragraph_sha256=use['evidence_paragraph_sha256'],use_summary=use['use_summary'],implementation_scope_note=use['implementation_scope_note'],supporting_evidence=copy.deepcopy(role['primary_anchors']),source_role_qualification=copy.deepcopy(qualified)))
 item=next(x for x in inventory if x['id']=='matrixeqtl');require(item['implementation_status']=='method-overlap'and item['paper_count']==4,'matrixeqtl already admitted/changed')
 item.update(current_coverage='native-subset-validated',existing_source=SOURCE,coverage_note=SCOPE,implementation_status='native-subset-validated',implementation_source=SOURCE,implementation_scope=SCOPE,validation_note='Nineteen component/contract tests pass. Nine complete packaged captures and fresh native replays per Windows/Linux platform match unchanged MatrixEQTL2.3 R tables: 19,622 associations, 498 feature minima and 19,458 independent R lm/GLS beta/SE comparisons per platform. Ten packaged refusals per platform preserve SKIP3/FAIL2 no-result semantics. See docs/literature/matrixeqtl-validation/QUALIFICATION.json.',paper_role_qualification={r['paper_id']:r for r in coverage})
 registry=copy.deepcopy(registry);next(x for x in registry if x['id']=='matrixeqtl').update(current_coverage='native-subset-validated',existing_source=SOURCE,coverage_note=SCOPE)
 summary.update(implementation_status_counts=dict(Counter(x['implementation_status']for x in inventory)),reviewed_tool_uses=1844,pending_tool_use_reviews=890,current_effective_registry=FOLDER+'/REGISTRY.json');summary['integration_family_counts'].update(scoped=177,native=35,upstream=142,including_existing_adapters=180)
 require(summary['implementation_status_counts']['native-subset-validated']==35 and summary['implementation_status_counts']['upstream-adapter-validated']==142 and summary['implementation_status_counts']['missing']==247,'Native transition counts differ from actual inventory')
 after=dict(before)
 for name,value in [(META[0],papers),(META[1],inventory),(META[2],summary),(META[7],ledger)]:after[name]=encoded(value)
 note=('# Current native MatrixEQTL additive checkpoint\n\n'+NOTICE+'\n\n**Warnings and required actions:** '+ACTION+'\n\nSee [workflow guide](../../matrixeqtl-native.md), [all four source roles](../matrixeqtl-source-audit/ROLES.json) and [qualification](../matrixeqtl-validation/QUALIFICATION.json). Earlier checkpoints below are historical.\n\n').encode()
 table=('| Paper | Reviewed use | Reported version |\n| --- | --- | --- |\n'+'\n'.join('| '+r['paper_id']+' | '+r['use_summary']+' | '+str(r['reported_version'])+' |'for r in roles)+'\n\n').encode()
 for name in META[3:7]:after[name]=note+(table if name in META[5:7]else b'')+b'---\n\n'+before[name]
 notice='<aside id="matrixeqtl-catalog-notice" style="margin:1rem;padding:1rem;border:2px solid #986619;overflow-wrap:anywhere"><h2>Native MatrixEQTL additive associations and warnings</h2><p>'+html.escape(NOTICE)+'</p><p><strong>Warnings and required actions:</strong> '+html.escape(ACTION)+'</p><p><a href="https://github.com/robbyjo/OmicsMatic/blob/main/docs/matrixeqtl-native.md">Source behavior, preparation, validation and recovery</a></p></aside>'
 for name in META[8:]:
  page=before[name].decode();require('id="matrixeqtl-catalog-notice"'not in page,'Already transitioned')
  if name==META[8]:
   match=re.search(r'(<script id="review-data" type="application/json">)(.*?)(</script>)',page,re.S);require(match and json.loads(match[2])==dict(papers=json.loads(before[META[0]]),tools=json.loads(before[META[1]]),summary=json.loads(before[META[2]])),'Prior interactive payload changed');payload=json.dumps(dict(papers=papers,tools=inventory,summary=summary),ensure_ascii=False).replace('<','\\u003c');page=page[:match.start(2)]+payload+page[match.end(2):]
  body=re.search(r'<body[^>]*>',page,re.I);marker=page.find('<site-header ',body.end());require(marker>=body.end(),'Report body boundary changed');after[name]=(page[:body.end()]+notice+'<details id="matrixeqtl-prior-catalog"><summary>Earlier catalog checkpoints (historical)</summary>'+page[body.end():marker]+'</details>'+page[marker:]).encode()
 return after,registry,coverage

def totals():return dict(papers=250,named_labels=453,provider_definitions=492,observations=2734,reviewed_uses=1844,pending_uses=890,scoped_families=177,native=35,upstream=142,missing_labels=247,new_source_reviews=4,recovered_observations=0,new_upstream_family_credit=0,new_native_family_credit=1,whole_goal_complete=False)

def check(root):
 folder=root/FOLDER;base=read(folder/'BASELINE.json');require(pin(folder/'metadata-before.zip')==base['archive']and pin(folder/'PREVIOUS-SHA256SUMS')==base['previous_checksums']and pin(root/Q)==base['qualification']and pin(root/ROLES)==base['source_roles']and pin(root/'tools/literature/matrixeqtl_catalog.py')==base['transformer'],'Transition context changed')
 with zipfile.ZipFile(folder/'metadata-before.zip')as archive:
  require(set(archive.namelist())==set(META),'Baseline population changed');before={n:archive.read(n)for n in META}
 require({n:identity(raw)for n,raw in before.items()}==base['metadata'],'Baseline bytes changed');registry=predecessor(root,before);after,registry,coverage=transition(before,registry,read(root/ROLES)['roles']);require(all((root/n).read_bytes()==raw for n,raw in after.items())and read(folder/'REGISTRY.json')==registry,'Canonical metadata differs from exact transition');require(read(root/COVERAGE)==dict(schema_version=1,tool_id='matrixeqtl',roles=coverage,new_family_credit=1,whole_paper_reproduced=False),'Role coverage changed');require(read(root/PROOF)==dict(schema_version=1,status='PASS_SCOPED_MATRIXEQTL_CATALOG_ADMISSION',totals=totals(),qualification=pin(root/Q),raw_source_text_published=False,released_binary_contains_workflow=False,website_reports_published=False),'Catalog proof changed')
 old,current=json.loads(before[META[0]]),json.loads(after[META[0]]);verify_fixed_cohort(root,root/DATA,current);require([[u for u in p['tools']if u['tool_id']!='matrixeqtl']for p in old]==[[u for u in p['tools']if u['tool_id']!='matrixeqtl']for p in current],'Unrelated observation changed');require([x for x in json.loads(before[META[1]])if x['id']!='matrixeqtl']==[x for x in json.loads(after[META[1]])if x['id']!='matrixeqtl'],'Unrelated inventory changed');ledger=json.loads(after[META[7]])['reviews'];require(ledger[:-4]==json.loads(before[META[7]])['reviews']and len({(r['pmcid'],r['tool_id'])for r in ledger})==len(ledger)==1844,'Prior/duplicate reviews changed')
 previous=checksums((folder/'PREVIOUS-SHA256SUMS').read_bytes());sums=checksums((root/DATA/'SHA256SUMS').read_bytes());require(set(sums)==set(previous)|{Path(COVERAGE).name,Path(PROOF).name},'Checksum population changed');allowed={Path(n).name for n in META if n.startswith(DATA+'/')};require(all(sums[n]==digest or n in allowed for n,digest in previous.items()),'Unrelated checksum refreshed');verify_sums(root,sums);return totals()

def apply(root,private,cache,out):
 from verify_matrixeqtl_workflows import verify
 require(not(root/FOLDER).exists()and out.is_relative_to(private)and not out.exists(),'NEW catalog/private paths required');qualification=verify(root,private);primary=source_audit(root,cache);before={n:(root/n).read_bytes()for n in META};registry=predecessor(root,before);after,registry,coverage=transition(before,registry,read(root/ROLES)['roles']);previous=(root/DATA/'SHA256SUMS').read_bytes();rows=checksums(previous);require(len(rows)==906,'Predecessor checksum count changed');verify_sums(root,rows);out.mkdir();folder=root/FOLDER;folder.mkdir()
 with zipfile.ZipFile(folder/'metadata-before.zip','x',compression=zipfile.ZIP_DEFLATED,compresslevel=9)as archive:
  for name,raw in before.items():archive.writestr(name,raw)
 (folder/'PREVIOUS-SHA256SUMS').write_bytes(previous);(folder/'BASELINE.json').write_bytes(encoded(dict(schema_version=1,archive=pin(folder/'metadata-before.zip'),metadata={n:identity(raw)for n,raw in before.items()},previous_checksums=pin(folder/'PREVIOUS-SHA256SUMS'),qualification=pin(root/Q),source_roles=pin(root/ROLES),transformer=pin(root/'tools/literature/matrixeqtl_catalog.py'))));(out/'PLAN.json').write_bytes(encoded(dict(before={n:identity(raw)for n,raw in before.items()},after={n:identity(raw)for n,raw in after.items()},qualification=qualification,primary=primary,totals=totals())))
 for i,(name,raw)in enumerate(after.items()):
  require((root/name).read_bytes()==before[name],'Concurrent catalog edit: '+name);stage=out/('staged-'+str(i));stage.write_bytes(raw);os.replace(stage,root/name)
 (folder/'REGISTRY.json').write_bytes(encoded(registry));(root/COVERAGE).write_bytes(encoded(dict(schema_version=1,tool_id='matrixeqtl',roles=coverage,new_family_credit=1,whole_paper_reproduced=False)));(root/PROOF).write_bytes(encoded(dict(schema_version=1,status='PASS_SCOPED_MATRIXEQTL_CATALOG_ADMISSION',totals=totals(),qualification=pin(root/Q),raw_source_text_published=False,released_binary_contains_workflow=False,website_reports_published=False)))
 for name in[n for n in META if n.startswith(DATA+'/')]+[COVERAGE,PROOF]:rows[Path(name).name]=pin(root/name)['sha256']
 newline='\r\n'if previous.count(b'\n')==previous.count(b'\r\n')else'\n';(root/DATA/'SHA256SUMS').write_bytes(''.join(digest+'  '+name+newline for name,digest in rows.items()).encode());result=check(root);(out/'COMPLETED.json').write_bytes(encoded(dict(status='PASS_EXACT_MATRIXEQTL_CATALOG_TRANSITION',totals=result)));return result
if __name__=='__main__':
 parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--root',type=Path,default=ROOT);parser.add_argument('--apply',action='store_true');parser.add_argument('--private',type=Path);parser.add_argument('--xml-cache',type=Path);parser.add_argument('--out',type=Path);args=parser.parse_args()
 if args.apply:require(all([args.private,args.xml_cache,args.out]),'Apply needs private qualification, XML cache and NEW output');result=apply(args.root.resolve(),args.private.resolve(),args.xml_cache.absolute(),args.out.resolve())
 else:result=check(args.root.resolve())
 print(json.dumps(result,indent=2))
